hero:
.hero { padding: 96px 24px 72px; background: linear-gradient(160deg, #f5f7ff 0%, #eef1fb 55%, #f9f7ff 100%); } .hero .hero__inner { max-width: 880px; margin: 0 auto; text-align: center; } .hero .hero__eyebrow { display: inline-block; margin: 0 0 20px; padding: 8px 18px; font-size: 13px; font-weight: 600; letter-spacing: 0.08em; text-transform: uppercase; color: #5b5bd6; background: #ffffff; border-radius: 999px; box-shadow: 0 6px 18px rgba(91, 91, 214, 0.12); } .hero .hero__title { margin: 0 0 16px; font-size: clamp(36px, 6vw, 60px); line-height: 1.08; font-weight: 800; letter-spacing: -0.02em; color: #1e1b4b; } .hero .hero__subtitle { margin: 0 0 24px; font-size: clamp(18px, 2.4vw, 22px); font-weight: 600; color: #6d5bd0; } .hero .hero__lead { max-width: 640px; margin: 0 auto; font-size: 17px; line-height: 1.7; color: #4b4b63; }

/* effects: hero */
.hero .hero__eyebrow { animation: hero-pulse-border 2.4s ease-in-out infinite; }
.hero .hero__title { transition: transform 0.4s cubic-bezier(0.2, 0.8, 0.2, 1), text-shadow 0.4s ease; }
.hero .hero__title:hover { transform: perspective(600px) rotateX(4deg) rotateY(-4deg); text-shadow: 0 8px 24px rgba(34, 197, 94, 0.35); }
.hero .hero__subtitle { transition: transform 0.4s cubic-bezier(0.2, 0.8, 0.2, 1), color 0.3s ease; }
.hero .hero__subtitle:hover { transform: perspective(600px) rotateX(3deg) rotateY(3deg); color: #16a34a; }
.hero .hero__lead { position: relative; padding: 24px 28px; border-radius: 20px; background: rgba(255, 255, 255, 0.55); backdrop-filter: blur(8px); -webkit-backdrop-filter: blur(8px); box-shadow: 0 8px 32px rgba(34, 197, 94, 0.12); overflow: hidden; transition: box-shadow 0.4s ease, transform 0.4s ease; }
.hero .hero__lead::after { content: ''; position: absolute; top: 0; left: -60%; width: 50%; height: 100%; background: linear-gradient(120deg, transparent 0%, rgba(134, 239, 172, 0.45) 50%, transparent 100%); transform: skewX(-20deg); transition: left 0.6s ease; pointer-events: none; }
.hero .hero__lead:hover::after, .hero .hero__lead:focus-within::after { left: 120%; }
.hero .hero__lead:hover, .hero .hero__lead:focus-within { box-shadow: 0 12px 40px rgba(34, 197, 94, 0.25); transform: translateY(-2px); }
@keyframes hero-pulse-border {
  0% { box-shadow: 0 0 0 0 rgba(34, 197, 94, 0.5), 0 6px 18px rgba(34, 197, 94, 0.15); }
  70% { box-shadow: 0 0 0 12px rgba(34, 197, 94, 0), 0 6px 18px rgba(34, 197, 94, 0.15); }
  100% { box-shadow: 0 0 0 0 rgba(34, 197, 94, 0), 0 6px 18px rgba(34, 197, 94, 0.15); }
}

projects:
.projects { padding: 72px 24px 96px; background: #fbfbff; } .projects .projects__inner { max-width: 1120px; margin: 0 auto; } .projects .projects__title { margin: 0 0 40px; font-size: clamp(28px, 4vw, 38px); font-weight: 800; letter-spacing: -0.02em; text-align: center; color: #1e1b4b; } .projects .projects__grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 24px; } .projects .projects__card { display: flex; flex-direction: column; gap: 14px; padding: 28px; text-decoration: none; background: #ffffff; border: 1px solid #eceafd; border-radius: 20px; box-shadow: 0 10px 30px rgba(46, 41, 120, 0.06); transition: transform 0.2s ease, box-shadow 0.2s ease; } .projects .projects__card:hover { transform: translateY(-4px); box-shadow: 0 18px 40px rgba(46, 41, 120, 0.12); } .projects .projects__icon { display: inline-flex; align-items: center; justify-content: center; width: 52px; height: 52px; color: #5b5bd6; background: #eef0ff; border-radius: 16px; } .projects .projects__card-title { margin: 0; font-size: 19px; font-weight: 700; color: #1e1b4b; } .projects .projects__card-text { margin: 0; font-size: 15px; line-height: 1.65; color: #5a5a72; }

/* effects: projects */
.projects .projects__title { position: relative; display: inline-block; left: 50%; transform: translateX(-50%); } .projects .projects__title-wave { position: absolute; left: 0; right: 0; bottom: -14px; height: 12px; color: #34d399; opacity: 0.9; } .projects .projects__title-wave svg { display: block; width: 100%; height: 100%; } .projects .projects__title-wave path { stroke-dasharray: 220; stroke-dashoffset: 220; animation: projects-wave-draw 2.4s ease-in-out infinite; } @keyframes projects-wave-draw { 0% { stroke-dashoffset: 220; } 45% { stroke-dashoffset: 0; } 55% { stroke-dashoffset: 0; } 100% { stroke-dashoffset: -220; } } .projects .projects__grid { perspective: 1200px; } .projects .projects__card { position: relative; overflow: hidden; transform-style: preserve-3d; transition: transform 0.3s ease-out, box-shadow 0.3s ease-out, border-color 0.3s ease-out; } .projects .projects__card:hover { transform: translateY(-6px) rotateX(6deg) rotateY(-6deg) scale(1.02); box-shadow: 0 22px 48px rgba(16, 185, 129, 0.18); border-color: #a7f3d0; } .projects .projects__accent { position: absolute; top: 0; left: 0; width: 100%; height: 4px; background: linear-gradient(90deg, #34d399, #6ee7b7, #a7f3d0); transform: skewX(-20deg) scaleX(0); transform-origin: left; transition: transform 0.35s ease-out; } .projects .projects__card:hover .projects__accent { transform: skewX(-20deg) scaleX(1); } .projects .projects__icon { transition: color 0.3s ease, background 0.3s ease, transform 0.3s ease-out; } .projects .projects__card:hover .projects__icon { color: #059669; background: #d1fae5; transform: translateZ(20px) rotate(-6deg); } .projects .projects__card-title { transition: color 0.3s ease; } .projects .projects__card:hover .projects__card-title { color: #047857; }

footer:
.footer { padding: 32px 24px; background: #f3f4fb; border-top: 1px solid #e6e6f5; } .footer .footer__inner { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 16px; max-width: 1120px; margin: 0 auto; } .footer .footer__copy { margin: 0; font-size: 14px; color: #6b6b85; } .footer .footer__nav { display: flex; gap: 24px; } .footer .footer__link { font-size: 14px; font-weight: 500; color: #5b5bd6; text-decoration: none; transition: color 0.2s ease; } .footer .footer__link:hover { color: #3f3fb0; }

/* effects: footer */
.footer { position: relative; overflow: hidden; }
.footer .footer__glow { position: absolute; border-radius: 50%; filter: blur(60px); opacity: 0.55; pointer-events: none; z-index: 0; }
.footer .footer__glow--1 { width: 320px; height: 320px; top: -120px; left: -80px; background: radial-gradient(circle, #7ef29d 0%, #3ddc84 40%, transparent 70%); animation: footer-glow-move 14s ease-in-out infinite alternate; }
.footer .footer__glow--2 { width: 280px; height: 280px; bottom: -100px; right: -60px; background: radial-gradient(circle, #b6ff7a 0%, #4be3a0 45%, transparent 72%); animation: footer-glow-move-reverse 18s ease-in-out infinite alternate; }
.footer .footer__inner { position: relative; z-index: 1; }
.footer .footer__link--gradient { position: relative; padding-bottom: 3px; }
.footer .footer__link--gradient::after { content: ''; position: absolute; left: 0; bottom: 0; height: 2px; width: 100%; background: linear-gradient(90deg, #3ddc84, #b6ff7a, #3ddc84); background-size: 200% 100%; border-radius: 2px; transform: scaleX(0); transform-origin: left; transition: transform 0.35s ease; }
.footer .footer__link--gradient:hover::after { transform: scaleX(1); animation: footer-underline-run 4s ease-in-out infinite; }
.footer .footer__link--slow::after { transition-duration: 0.6s; }
.footer .footer__link--slow:hover::after { animation-duration: 6s; }
@keyframes footer-glow-move { 0% { transform: translate(0, 0) scale(1); } 50% { transform: translate(60px, 40px) scale(1.15); } 100% { transform: translate(20px, -30px) scale(0.95); } }
@keyframes footer-glow-move-reverse { 0% { transform: translate(0, 0) scale(1); } 50% { transform: translate(-70px, -50px) scale(1.2); } 100% { transform: translate(-30px, 30px) scale(0.9); } }
@keyframes footer-underline-run { 0% { background-position: 0% 50%; } 50% { background-position: 100% 50%; } 100% { background-position: 0% 50%; } }
